"""VIR Vision CLI for validated scenes and opt-in local image perception."""

import argparse
from dataclasses import asdict, replace
from datetime import datetime, timezone
import importlib.util
import json
import logging
from pathlib import Path
import platform
import sys
from time import perf_counter

from virvision import __version__
from virvision.config import load_config
from virvision.perception.image import SUPPORTED_SUFFIXES
from virvision.sample import mock_scene
from virvision.scene.models import scene_from_dict, scene_to_dict
from virvision.vir.parser import parse_vir
from virvision.vir.query_filter import analyze_query
from virvision.vir.serializer import serialize_vir
from virvision.vir.token_budget import build_vir
from virvision.vir.tokenizers import load_tokenizer

LOG = logging.getLogger("virvision")


def _read_scene(path: Path):
    if path.suffix.lower() == ".vir":
        return parse_vir(path.read_text(encoding="utf-8"))
    if path.suffix.lower() != ".json":
        raise ValueError("Expected a scene.json or scene.vir input")
    return scene_from_dict(json.loads(path.read_text(encoding="utf-8")))


def _json(value) -> str:
    return json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False)


def _write(value: str, path: Path | None, *, trailing_newline: bool = True) -> None:
    text = value + ("\n" if trailing_newline else "")
    if path is None:
        if not trailing_newline and hasattr(sys.stdout, "buffer"):
            # Bypass platform newline translation for a piped VIR representation.
            sys.stdout.buffer.write(text.encode("utf-8"))
        else:
            sys.stdout.write(text)
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="virvision", description="Kutarya Lens local tools")
    parser.add_argument("--version", action="version", version=__version__)
    parser.add_argument("--debug", action="store_true")
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("demo", "vir", "compare"):
        command = commands.add_parser(name)
        if name != "demo":
            command.add_argument("scene", type=Path)
        command.add_argument("--query")
        command.add_argument("--budget", type=int)
        command.add_argument("--config", type=Path)
        tokenizer = command.add_mutually_exclusive_group()
        tokenizer.add_argument("--tokenizer", help="Local tokenizer.json file or its directory")
        tokenizer.add_argument(
            "--mock", action="store_true", help="Use MOCK UTF8 bytes, not model tokens"
        )
        command.add_argument("--output", type=Path)
        command.add_argument(
            "--metadata", type=Path, help="Save selection/measurement metadata separately"
        )
        command.add_argument(
            "--full", action="store_true", help="Disable query pruning; budget still applies"
        )
        if name != "demo":
            command.add_argument("--warmup", type=int, help="Override perception warm-up runs")
            command.add_argument("--device", choices=("auto", "cpu", "cuda"))
    for name in ("analyze", "validate"):
        command = commands.add_parser(name)
        command.add_argument("scene", type=Path)
        command.add_argument("--output", type=Path)
        if name == "analyze":
            command.add_argument("--config", type=Path)
            command.add_argument("--warmup", type=int, help="Override perception warm-up runs")
            command.add_argument("--device", choices=("auto", "cpu", "cuda"))
    describe = commands.add_parser("describe", help="Produce grounded natural image text")
    describe.add_argument("scene", type=Path)
    describe.add_argument("--language", choices=("tr", "en"))
    describe.add_argument("--detail", choices=("compact", "balanced", "detailed"))
    describe.add_argument(
        "--format", dest="output_format", choices=("text", "json"), default="text"
    )
    describe.add_argument("--config", type=Path)
    describe.add_argument("--warmup", type=int, help="Override perception warm-up runs")
    describe.add_argument("--device", choices=("auto", "cpu", "cuda"))
    describe.add_argument("--output", type=Path)
    doctor = commands.add_parser("doctor")
    doctor.add_argument("--tokenizer")
    return parser


def run(args: argparse.Namespace) -> int:
    if args.command == "doctor":
        info = {
            "version": __version__,
            "python": platform.python_version(),
            "product": "Kutarya Lens",
            "phase": "milestone_3",
            "kcs_version": "KCS-1",
            "tokenizers_installed": importlib.util.find_spec("tokenizers") is not None,
            "pillow_installed": importlib.util.find_spec("PIL") is not None,
            "ultralytics_installed": importlib.util.find_spec("ultralytics") is not None,
            "easyocr_installed": importlib.util.find_spec("easyocr") is not None,
            "vision_inference": "local_optional",
            "llm_inference": "not_implemented",
        }
        if args.tokenizer:
            counter = load_tokenizer(args.tokenizer)
            info.update(tokenizer=counter.name, is_model_tokenizer=counter.is_model_tokenizer)
        print(_json(info))
        return 0
    config = load_config(getattr(args, "config", None))
    if getattr(args, "device", None) is not None:
        perception = replace(
            config.perception,
            detector=replace(config.perception.detector, device=args.device),
            ocr=replace(config.perception.ocr, device=args.device),
        )
        config = replace(config, perception=perception)
    if getattr(args, "warmup", None) is not None:
        config = replace(config, perception=replace(config.perception, warmup_runs=args.warmup))

    if args.command == "describe":
        language = args.language or config.lens.language
        detail = args.detail or config.lens.detail
        if args.scene.suffix.lower() in SUPPORTED_SUFFIXES:
            from virvision.lens import Lens

            result = Lens(config=config).analyze(args.scene, language=language, detail=detail)
            value = result.to_dict()
            text = _json(value) if args.output_format == "json" else result.text
        else:
            from virvision.kcs.model import KCS_VERSION
            from virvision.kcs.runtime import KCSProfile, compile_execution_plan

            scene = _read_scene(args.scene)
            plan = compile_execution_plan(
                KCSProfile(language, detail, config.spatial), thresholds=config.confidence
            )
            described = plan.execute(scene)
            value = {
                "text": described.text,
                "objects": len(described.field.scene.objects),
                "ocr_items": len(described.field.scene.texts),
                "relations": len(described.field.scene.relations),
                "processing_ms": described.metrics.runtime_total_ms,
                "warnings": list(described.projection.warnings),
                "language": language,
                "detail": detail,
                "kcs_version": KCS_VERSION,
                "metrics": {"kcs_ms": described.metrics.to_dict()},
                "scene": scene_to_dict(described.field.scene),
            }
            text = _json(value) if args.output_format == "json" else described.text
        _write(text, args.output)
        return 0

    image_input = (
        args.command in {"analyze", "vir", "compare"}
        and args.scene.suffix.lower() in SUPPORTED_SUFFIXES
    )
    perception_result = None
    if image_input:
        from virvision.perception import create_pipeline

        perception_result = create_pipeline(config.perception).analyze(args.scene)
        scene = perception_result.scene
    else:
        scene = mock_scene() if args.command == "demo" else _read_scene(args.scene)

    if args.command in ("analyze", "validate"):
        if args.command == "validate":
            # Exercise both formats before acknowledging validity.
            if parse_vir(serialize_vir(scene)) != scene:
                raise ValueError("Scene round-trip validation failed")
            result = {
                "valid": True,
                "objects": len(scene.objects),
                "texts": len(scene.texts),
                "relations": len(scene.relations),
                "image_inference_performed": False,
            }
        elif perception_result is not None:
            result = perception_result.to_dict()
        else:
            result = scene_to_dict(scene)
        _write(_json(result), args.output)
        return 0
    spec = "mock" if args.mock else args.tokenizer or config.tokenizer_path
    if spec is None:
        raise ValueError(
            "Provide --tokenizer PATH for real token counts, or --mock for clearly labeled mock units. No tokenizer was downloaded."
        )
    counter = load_tokenizer(spec)
    if not counter.is_model_tokenizer:
        LOG.warning(
            "MOCK: counts and budget are UTF8 bytes, NOT model tokens; no inference or accuracy measurement."
        )
    started = perf_counter()
    result = build_vir(
        scene,
        tokenizer=counter,
        query=args.query,
        token_budget=args.budget if args.budget is not None else config.budget,
        weights=config.weights,
        thresholds=config.confidence,
        query_aware=not args.full,
    )
    build_ms = (perf_counter() - started) * 1000
    metadata = {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "source": "hand_authored_mock_scene" if args.command == "demo" else str(args.scene),
        "tokenizer": result.tokenizer,
        "is_model_tokenizer": result.is_model_tokenizer,
        "unit": result.unit,
        "budget": result.budget,
        "measured_units": result.measured_units,
        "representation_tokens": result.representation_tokens,
        "vir_build_ms": build_ms,
        "selected_items": result.selected_items,
        "dropped_items": result.dropped_items,
        "confidence_filtered_items": result.confidence_filtered_items,
        "query_pruned_items": result.query_pruned_items,
        "complete_scene": result.complete,
        "effective_query": result.scene.query,
        "query_aware": not args.full,
        "intent": asdict(analyze_query(result.scene.query if not args.full else None)),
        "configuration": {**asdict(config), "budget": result.budget, "tokenizer_path": spec},
        "image_inference_performed": perception_result is not None,
        "llm_inference_performed": False,
    }
    if perception_result is not None:
        metadata["perception"] = perception_result.to_dict()
    if args.metadata:
        _write(_json(metadata), args.metadata)
    if args.command == "compare":
        full = serialize_vir(scene)
        json_text = json.dumps(
            scene_to_dict(scene), ensure_ascii=False, separators=(",", ":"), allow_nan=False
        )
        _write(
            _json(
                {
                    "measurement": metadata,
                    "representations": [
                        {
                            "method": "json_full",
                            "units": counter.count(json_text),
                            "same_information_as_full_vir": True,
                        },
                        {
                            "method": "vir_full",
                            "units": counter.count(full),
                            "same_information_as_full_vir": True,
                        },
                        {
                            "method": "vir_selected",
                            "units": result.measured_units,
                            "same_information_as_full_vir": result.scene == scene,
                        },
                    ],
                    "quality": "unmeasured",
                    "note": "Selection may lose information; standalone representation tokens exclude prompts and chat templates.",
                }
            ),
            args.output,
        )
    else:
        # Preserve the exact measured bytes, including on Windows and when piped.
        _write(result.text, args.output, trailing_newline=False)
        LOG.info(
            "VIR: %d/%d %s; %d budget-dropped items; build %.3f ms",
            result.measured_units,
            result.budget,
            result.unit,
            len(result.dropped_items),
            build_ms,
        )
    return 0


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    logging.basicConfig(
        level=logging.DEBUG if args.debug else logging.INFO, format="%(levelname)s %(message)s"
    )
    try:
        return run(args)
    except (OSError, ValueError, TypeError, ImportError, RuntimeError) as exc:
        if args.debug:
            LOG.exception("Command failed")
        else:
            print(f"Error: {exc}", file=sys.stderr)
        return 2
